//! The client against the reference implementation's own output.
//!
//! The fixtures in `tests/fixtures/` are Garmin payloads; `expected.json` is
//! what the **Python reference implementation** produces for them, generated by
//! `tests/fixtures/make_expected.py` calling the reference's own functions
//! (`_canonical_from_detail`, `_as_list`, `_bounded_date_range`,
//! `_athlete_from_personal`). This test proves the Rust client produces the
//! same numbers.
//!
//! The comparison follows `docs/core-contract.md` §8: strings, booleans, null
//! and integers are equal exactly; floating point numbers differ by at most
//! `1e-9 × max(1, |golden value|)`.

// An integration test is its own crate, not a `#[cfg(test)]` module, so the
// workspace's `allow-*-in-tests` configuration does not reach it.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

mod common;

use std::fs;
use std::path::PathBuf;

use common::{Reply, StubServer};
use serde_json::{Map, Value};
use stride_garmin::{ActivityDetail, GarminClient};

const PROFILE_PATH: &str = "/userprofile-service/userprofile/settings";
const ACTIVITIES_PATH: &str = "/activitylist-service/activities/search/activities";
const DETAIL_PATH: &str = "/activity-service/activity/19012837465";
const DETAIL_FALLBACK_PATH: &str = "/activity-service/activity/19012999001";
const WORKOUTS_PATH: &str = "/activity-service/activity/19012837465/workouts";
const ZONES_PATH: &str = "/biometric-service/heartRateZones/v2";
const SLEEP_PATH: &str = "/sleep-service/sleep/dailySleep";
const SLEEP_RANGE_PATH: &str = "/sleep-service/sleep/dailySleepSummariesByDate";
const HRV_PATH: &str = "/hrv-service/hrv/2026-03-07";
const HRV_RANGE_PATH: &str = "/hrv-service/hrv/daily/2026-01-01/2026-01-31";
const DAILY_HR_PATH: &str = "/wellness-service/wellness/dailyHeartRate";
const DAILY_SUMMARY_PATH: &str = "/usersummary-service/usersummary/daily";
const BODY_BATTERY_PATH: &str = "/wellness-service/wellness/bodyBattery/reports/daily";
const STRESS_PATH: &str = "/usersummary-service/stats/stress/daily/2026-01-01/2026-01-31";
const STEPS_PATH: &str = "/usersummary-service/stats/steps/daily/2026-01-01/2026-01-31";
const WEIGHT_PATH: &str = "/weight-service/weight/all/2026-01-01/2026-01-31";

fn fixture(name: &str) -> Value {
    let path: PathBuf = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join(name);
    let text = fs::read_to_string(&path).expect("the fixture is there");
    serde_json::from_str(&text).expect("the fixture is JSON")
}

fn expected() -> Value {
    fixture("expected.json")
}

/// A stub that answers the given routes with the given fixtures.
fn stub_with(routes: &[(&str, &str, &str)]) -> StubServer {
    let stub = StubServer::start();
    stub.push(
        "POST",
        stride_garmin::TOKEN_PATH,
        Reply::text("eyJhbGciOiJIUzI1NiJ9.golden-jwt.golden"),
    );
    for (method, path, name) in routes {
        stub.push(method, path, Reply::json(fixture(name)));
    }
    stub
}

fn client_for(stub: &StubServer) -> GarminClient {
    GarminClient::with_base_url("GOLDEN-KEY-not-a-real-key", &stub.base_url())
        .expect("the stub is a loopback host")
}

/// The canonical activity, as a JSON object the fixture can be compared with.
fn canonical_value(detail: &ActivityDetail) -> Value {
    let mut map = Map::new();
    map.insert(
        "external_id".into(),
        Value::String(detail.external_id.clone()),
    );
    map.insert("name".into(), Value::String(detail.name.clone()));
    map.insert(
        "sport_type".into(),
        Value::String(detail.sport_type.clone()),
    );
    map.insert("start_time".into(), optional(detail.start_time.clone()));
    map.insert("local_date".into(), optional(detail.local_date.clone()));
    map.insert("day_of_week".into(), optional(detail.day_of_week.clone()));
    map.insert("distance_m".into(), Value::from(detail.distance_m));
    map.insert("moving_time_s".into(), Value::from(detail.moving_time_s));
    map.insert("elapsed_time_s".into(), Value::from(detail.elapsed_time_s));
    map.insert(
        "elevation_gain_m".into(),
        Value::from(detail.elevation_gain_m),
    );
    map.insert("avg_hr".into(), optional_f64(detail.avg_hr));
    map.insert("max_hr".into(), optional_f64(detail.max_hr));
    map.insert("min_hr".into(), optional_f64(detail.min_hr));
    map.insert("calories".into(), optional_f64(detail.calories));
    map.insert("avg_cadence".into(), optional_f64(detail.avg_cadence));
    map.insert("max_cadence".into(), optional_f64(detail.max_cadence));
    map.insert("avg_speed_ms".into(), optional_f64(detail.avg_speed_ms));
    map.insert("max_speed_ms".into(), optional_f64(detail.max_speed_ms));
    map.insert("device".into(), optional(detail.device.clone()));
    Value::Object(map)
}

fn optional(value: Option<String>) -> Value {
    match value {
        Some(text) => Value::String(text),
        None => Value::Null,
    }
}

fn optional_f64(value: Option<f64>) -> Value {
    match value {
        Some(number) => Value::from(number),
        None => Value::Null,
    }
}

/// The comparison rule of `docs/core-contract.md` §8.
fn assert_close(actual: &Value, expected: &Value, path: &str) {
    match (actual, expected) {
        (Value::Number(actual), Value::Number(expected)) => {
            let actual = actual.as_f64().expect("a number");
            let expected = expected.as_f64().expect("a number");
            let tolerance = 1e-9 * f64::max(1.0, expected.abs());
            assert!(
                (actual - expected).abs() <= tolerance,
                "{path}: {actual} != {expected}"
            );
        }
        (Value::Object(actual), Value::Object(expected)) => {
            for (key, value) in expected {
                let actual = actual.get(key).unwrap_or(&Value::Null);
                assert_close(actual, value, &format!("{path}.{key}"));
            }
        }
        (Value::Array(actual), Value::Array(expected)) => {
            assert_eq!(actual.len(), expected.len(), "{path}: the lengths differ");
            for (index, (actual, expected)) in actual.iter().zip(expected).enumerate() {
                assert_close(actual, expected, &format!("{path}[{index}]"));
            }
        }
        _ => assert_eq!(actual, expected, "{path}"),
    }
}

#[test]
fn the_golden_profile_matches_the_reference() {
    let stub = stub_with(&[("GET", PROFILE_PATH, "profile.json")]);
    let client = client_for(&stub);

    let profile = client.profile().expect("the profile read succeeds");
    let expected = expected();

    assert_close(
        &Value::String(profile.athlete_name().unwrap_or_default().to_owned()),
        &expected["profile"]["athlete_name"],
        "profile.athlete_name",
    );
    assert_close(
        &Value::Object(profile.raw.clone()),
        &expected["profile"]["raw"],
        "profile.raw",
    );
}

#[test]
fn the_golden_canonical_activity_matches_the_reference() {
    let stub = stub_with(&[("GET", DETAIL_PATH, "activity_detail.json")]);
    let client = client_for(&stub);

    let detail = client
        .activity_detail_canonical("19012837465")
        .expect("the detail read succeeds");
    let expected = expected();

    assert_close(
        &canonical_value(&detail),
        &expected["activity_detail"],
        "activity_detail",
    );
}

#[test]
fn the_golden_canonical_activity_falls_back_to_the_list_item() {
    let stub = stub_with(&[("GET", DETAIL_FALLBACK_PATH, "activity_detail_fallback.json")]);
    let client = client_for(&stub);

    let detail_payload = client
        .activity_detail("19012999001")
        .expect("the detail read succeeds");
    let list_item = fixture("activity_list.json")["activityList"][1].clone();

    let detail = ActivityDetail::from_value(&detail_payload, Some(&list_item))
        .expect("the detail canonicalises");
    let expected = expected();

    assert_close(
        &canonical_value(&detail),
        &expected["activity_detail_fallback"],
        "activity_detail_fallback",
    );
}

#[test]
fn the_golden_activity_list_matches_the_reference() {
    let stub = stub_with(&[("GET", ACTIVITIES_PATH, "activity_list.json")]);
    let client = client_for(&stub);

    let to = chrono::Utc::now();
    let activities = client
        .activities(to - chrono::Duration::days(7), to)
        .expect("the activity list succeeds");
    let expected = expected();

    let ids: Vec<Value> = activities
        .iter()
        .map(|activity| Value::String(activity.external_id.clone()))
        .collect();
    assert_close(
        &Value::Array(ids),
        &expected["activity_list_ids"],
        "activities.ids",
    );

    let names: Vec<Value> = activities
        .iter()
        .map(|activity| Value::String(activity.name.clone()))
        .collect();
    assert_close(
        &Value::Array(names),
        &expected["activity_list_names"],
        "activities.names",
    );

    // The reference reads the id, the name and the start time from a list item
    // on its own; the sport is extra, the reference takes it from the detail.
    let listed = &expected["activity_list"];
    for (index, activity) in activities.iter().enumerate() {
        assert_eq!(
            activity.external_id,
            listed[index]["external_id"].as_str().unwrap(),
            "activity {index} id"
        );
        assert_eq!(
            activity.name,
            listed[index]["name"].as_str().unwrap(),
            "activity {index} name"
        );
    }
    let sports: Vec<Value> = activities
        .iter()
        .map(|activity| Value::String(activity.sport_type.clone().unwrap_or_default()))
        .collect();
    assert_close(
        &Value::Array(sports),
        &expected["activity_list_sports"],
        "activities.sports",
    );
}

#[test]
fn the_golden_envelopes_match_the_reference() {
    let stub = stub_with(&[
        ("GET", ACTIVITIES_PATH, "activity_list.json"),
        ("GET", WORKOUTS_PATH, "workouts.json"),
        ("GET", BODY_BATTERY_PATH, "body_battery.json"),
        ("GET", STRESS_PATH, "stress.json"),
        ("GET", STEPS_PATH, "steps.json"),
        ("GET", HRV_RANGE_PATH, "hrv_range.json"),
        ("GET", SLEEP_RANGE_PATH, "sleep_range.json"),
        ("GET", WEIGHT_PATH, "weight.json"),
    ]);
    let client = client_for(&stub);
    let expected = expected();

    let page = client
        .activity_page(0, 100, "2026-01-01", "2026-01-31")
        .expect("the activity list succeeds");
    let page_ids: Vec<Value> = page
        .iter()
        .map(|activity| Value::String(activity.external_id.clone()))
        .collect();
    let expected_ids: Vec<Value> = expected["lists"]["activities"]
        .as_array()
        .expect("a list")
        .iter()
        .map(|item| Value::String(item["activityId"].to_string()))
        .collect();
    assert_close(
        &Value::Array(page_ids),
        &Value::Array(expected_ids),
        "lists.activities",
    );

    assert_close(
        &Value::Array(
            client
                .activity_workouts("19012837465")
                .expect("the workouts succeed"),
        ),
        &expected["lists"]["workouts"],
        "lists.workouts",
    );
    assert_close(
        &Value::Array(
            client
                .body_battery_list("2026-01-01", "2026-01-31")
                .expect("the body battery succeeds"),
        ),
        &expected["lists"]["body_battery"],
        "lists.body_battery",
    );
    assert_close(
        &Value::Array(
            client
                .stress_list("2026-01-01", "2026-01-31")
                .expect("the stress succeeds"),
        ),
        &expected["lists"]["stress"],
        "lists.stress",
    );
    assert_close(
        &Value::Array(
            client
                .steps_list("2026-01-01", "2026-01-31")
                .expect("the steps succeed"),
        ),
        &expected["lists"]["steps"],
        "lists.steps",
    );
    assert_close(
        &Value::Array(
            client
                .hrv_range("2026-01-01", "2026-01-31")
                .expect("the hrv range succeeds"),
        ),
        &expected["lists"]["hrv_range"],
        "lists.hrv_range",
    );
    assert_close(
        &Value::Array(
            client
                .sleep_range("2026-01-01", "2026-01-31")
                .expect("the sleep range succeeds"),
        ),
        &expected["lists"]["sleep_range"],
        "lists.sleep_range",
    );
    assert_close(
        &Value::Array(
            client
                .weight_list("2026-01-01", "2026-01-31")
                .expect("the weight succeeds"),
        ),
        &expected["lists"]["weight"],
        "lists.weight",
    );
}

#[test]
fn the_golden_wellness_payloads_are_returned_untouched() {
    let stub = stub_with(&[
        ("GET", SLEEP_PATH, "sleep.json"),
        ("GET", HRV_PATH, "hrv.json"),
        ("GET", DAILY_HR_PATH, "daily_heart_rate.json"),
        ("GET", DAILY_SUMMARY_PATH, "daily_summary.json"),
        ("GET", ZONES_PATH, "heart_rate_zones.json"),
    ]);
    let client = client_for(&stub);
    let expected = expected();

    assert_close(
        &client.sleep("2026-03-07").expect("the sleep succeeds"),
        &expected["payloads"]["sleep"],
        "payloads.sleep",
    );
    assert_close(
        &client.hrv("2026-03-07").expect("the hrv succeeds"),
        &expected["payloads"]["hrv"],
        "payloads.hrv",
    );
    assert_close(
        &client
            .daily_heart_rate("2026-03-07")
            .expect("the daily heart rate succeeds"),
        &expected["payloads"]["daily_heart_rate"],
        "payloads.daily_heart_rate",
    );
    assert_close(
        &client
            .daily_summary("2026-03-07")
            .expect("the daily summary succeeds"),
        &expected["payloads"]["daily_summary"],
        "payloads.daily_summary",
    );

    let zones = client.heart_rate_zones().expect("the zone model succeeds");
    assert_close(
        &Value::Object(zones.raw.clone()),
        &expected["payloads"]["zones"],
        "payloads.zones",
    );
}

#[test]
fn the_golden_windows_are_clamped_the_way_the_reference_clamps_them() {
    let stub = StubServer::start();
    stub.push(
        "POST",
        stride_garmin::TOKEN_PATH,
        Reply::text("eyJhbGciOiJIUzI1NiJ9.golden-jwt.golden"),
    );
    for _ in 0..3 {
        stub.push(
            "GET",
            BODY_BATTERY_PATH,
            Reply::json(fixture("body_battery.json")),
        );
    }
    let client = client_for(&stub);
    let expected = expected();

    let cases = [
        ("2026-01-01", "2026-01-31", "short"),
        ("2025-01-01", "2026-01-31", "long"),
        ("2026-03-10", "2026-03-01", "inverted"),
    ];
    for (from, to, name) in cases {
        client
            .body_battery_list(from, to)
            .expect("the body battery succeeds");
        let requests = stub.requests_for("GET", BODY_BATTERY_PATH);
        let request = requests.last().expect("the request is recorded");
        let start = query_value(&request.query, "startDate");
        let end = query_value(&request.query, "endDate");
        assert_close(
            &Value::String(start),
            &expected["dates"][name][0],
            &format!("dates.{name}.start"),
        );
        assert_close(
            &Value::String(end),
            &expected["dates"][name][1],
            &format!("dates.{name}.end"),
        );
    }
}

fn query_value(query: &str, key: &str) -> String {
    query
        .split('&')
        .find_map(|pair| pair.strip_prefix(&format!("{key}=")))
        .unwrap_or_default()
        .to_owned()
}
